import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.DhQimoSI.js";const g=JSON.parse('{"title":"Why Mosaic exists","description":"","frontmatter":{},"headers":[],"relativePath":"welcome/why.md","filePath":"welcome/why.md"}'),r={name:"welcome/why.md"};function n(i,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="why-mosaic-exists" tabindex="-1">Why Mosaic exists <a class="header-anchor" href="#why-mosaic-exists" aria-label="Permalink to &quot;Why Mosaic exists&quot;">​</a></h1><p>Most geometric and structured data is exchanged as <strong>whole files</strong>. One party exports a model and another imports it. When something changes, the whole model is exported again. Every exchange is a snapshot, and a snapshot forgets things:</p><ul><li><strong>Who changed what.</strong> The new export holds the result, not the edit, so the history of a model lives in people&#39;s heads and in email.</li><li><strong>Where a piece came from.</strong> Once two sources are merged into one file, the seams are gone. A wall from the architect and a duct from the engineer are just two objects.</li><li><strong>What another file was pointing at.</strong> Ids are often regenerated on export, so a reference from one model into another breaks every time the other is re-exported.</li></ul><p>That works while one tool owns the whole picture. It stops working when many people, in many tools, each own a part of it, which is the normal case on a building, a site or a product.</p><h2 id="lessons-from-existing-formats" tabindex="-1">Lessons from existing formats <a class="header-anchor" href="#lessons-from-existing-formats" aria-label="Permalink to &quot;Lessons from existing formats&quot;">​</a></h2><p>Mosaic borrows from formats that each solve part of this:</p><table tabindex="0"><thead><tr><th>From</th><th>Mosaic takes</th><th>What it addresses</th></tr></thead><tbody><tr><td><strong>USD</strong></td><td>Layering: later opinions over earlier ones, composed when read</td><td>USD&#39;s composition is powerful but complex, and its tooling is heavy</td></tr><tr><td><strong>ECS</strong></td><td>Entities are ids, and data lives in components</td><td>Data stays decoupled from the use cases that read it, so a new use case doesn&#39;t need a new format</td></tr><tr><td><strong>JSON / JSON Schema</strong></td><td>Every component type is a schema, carried in the file</td><td>Any data can be validated, and generated into typed code, without a central registry</td></tr><tr><td><strong>glTF</strong></td><td>Geometry, materials and textures as compact, renderable components</td><td>Geometry composes straight into a file every viewer already reads</td></tr></tbody></table><h2 id="what-it-does-instead" tabindex="-1">What it does instead <a class="header-anchor" href="#what-it-does-instead" aria-label="Permalink to &quot;What it does instead&quot;">​</a></h2><ul><li><strong>Edits are layers, not overwrites.</strong> A file is a list of sections, each with an author, a time, an application and a message. A later section sets, deletes or passes through what came before, without restating the rest.</li><li><strong>Sources keep their identity.</strong> A file imports others rather than copying them in. Composing merges everything into one picture, but each node is still written in the file that owns it, and a viewer can show which one that is.</li><li><strong>Ids are stable.</strong> Nodes are uuids, and converters can derive them from the source (an IFC <code>GlobalId</code>, or a seed from the file name), so re-converting a model leaves every reference into it intact.</li><li><strong>It&#39;s unopinionated about data.</strong> Mosaic has a handful of <a href="/mosaic/dist/docs/standard/core-components">core components</a> for naming, placement, hierarchy and types. Everything else is whatever schema you bring.</li><li><strong>Assemblies and types are built in.</strong> <code>core::child</code> places one node under many parents, sharing its geometry. <code>core::inherit</code> makes a node <em>be</em> a type and take that type&#39;s components, so a change to the type is a change to every instance.</li><li><strong>Files and APIs say the same thing.</strong> The same data can move as a <code>.tsr</code> archive or through the <a href="/mosaic/dist/docs/standard/api">API</a>, which adds versioning and fetching just the nodes you need.</li></ul>',9)])])}const p=t(r,[["render",n]]);export{g as __pageData,p as default};
